from django.db import migrations, models


def converter_o_total_em_parcela(apps, schema_editor):
    """Transforma o total guardado na parcela manual, sem perder a decisão de ninguém.

    O zero antigo era a convenção "não comprar agora": vira `nao_comprar`, que diz o
    mesmo sem envelhecer quando a sugestão muda. Linha sem sugestão guardada (não
    deveria existir, mas o banco permite) fica com a parcela igual ao total, que é o
    que mais se aproxima do que a pessoa quis.
    """
    Ajuste = apps.get_model("compras", "AjusteDeCompra")
    for ajuste in Ajuste.objects.all():
        sugerida = ajuste.sugerida or 0
        if ajuste.quantidade == 0 and sugerida > 0:
            ajuste.nao_comprar = True
            ajuste.a_mais = 0
        else:
            ajuste.a_mais = ajuste.quantidade - sugerida
        ajuste.save(update_fields=["a_mais", "nao_comprar"])


def voltar_a_parcela_para_total(apps, schema_editor):
    """Volta atrás: o total vira de novo o número guardado, para a versão antiga ler."""
    Ajuste = apps.get_model("compras", "AjusteDeCompra")
    for ajuste in Ajuste.objects.all():
        if ajuste.nao_comprar:
            ajuste.quantidade = 0
        else:
            ajuste.quantidade = max(0, (ajuste.sugerida or 0) + (ajuste.a_mais or 0))
        ajuste.save(update_fields=["quantidade"])


